package mz.bam.seeky.android;

import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;

/** Durable job state. Only fsynced PCM is committed; a restart truncates uncommitted audio. */
final class NarrationJob {
 final File directory,file;final JSONObject data;
 NarrationJob(File directory,JSONObject data){this.directory=directory;file=new File(directory,"job.json");this.data=data;}
 static File root(Context c){File f=new File(c.getFilesDir(),"narration-jobs");f.mkdirs();return f;}
 static NarrationJob create(Context c,Intent intent)throws Exception{File dir=new File(root(c),UUID.randomUUID().toString());if(!dir.mkdir())throw new IOException("Não foi possível preparar a narração.");JSONObject value=new JSONObject();String[] keys={"name","display_title","engine","voice","language","tree","background","selection"};for(String key:keys)if(intent.hasExtra(key))value.put(key,intent.getStringExtra(key));value.put("uri",intent.getData().toString()).put("mime",intent.getType()).put("first",intent.getIntExtra("first",0)).put("last",intent.getIntExtra("last",0)).put("part",intent.getIntExtra("first",0)).put("offset",0).put("piece",1).put("seq",1).put("bytes",0).put("saved",0).put("skipped",0).put("frames",0).put("single",intent.getBooleanExtra("single",false)).put("online",intent.getBooleanExtra("online",false)).put("rate",intent.getFloatExtra("rate",1)).put("background_volume",intent.getIntExtra("background_volume",15)).put("status","prepared").put("created",System.currentTimeMillis()).put("speech_layout_version",1).put("title_pause_ms",Math.max(500,Math.min(5000,c.getSharedPreferences("seeky",0).getInt("speech_title_pause_ms",2000)))).put("pronunciation",c.getSharedPreferences(VoiceText.PREF,0).getString("rules","[]")).put("workspace_id",c.getSharedPreferences("reading_tools",0).getString("workspace_id",""));NarrationJob job=new NarrationJob(dir,value);job.save();return job;}
 static NarrationJob load(Context c,String id)throws Exception{if(id==null||!id.matches("[a-f0-9-]{36}"))throw new IOException("Narração indisponível.");File dir=new File(root(c),id),f=new File(dir,"job.json");if(!f.isFile()||f.length()>131072)throw new IOException("Registo de narração indisponível.");return new NarrationJob(dir,new JSONObject(new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8)));}
 static List<NarrationJob> list(Context c,String source){List<NarrationJob> out=new ArrayList<>();File[] files=root(c).listFiles();if(files!=null)for(File dir:files){try{NarrationJob job=load(c,dir.getName());if(job.s("workspace_id").equals(c.getSharedPreferences("reading_tools",0).getString("workspace_id",""))&&(source==null||source.equals(job.s("uri")))&&!job.s("status").equals("complete"))out.add(job);}catch(Exception ignored){}}out.sort((a,b)->Long.compare(b.n("updated"),a.n("updated")));return out;}
 String id(){return directory.getName();}String s(String k){return data.optString(k,"");}long n(String k){return data.optLong(k,0);}int i(String k){return data.optInt(k,0);}boolean b(String k){return data.optBoolean(k,false);}void put(String key,Object value){try{if(value instanceof String&&Arrays.asList("book","author","chapter","display_title","error").contains(key))value=AudioTitles.limit((String)value,1024,4096);data.put(key,value);}catch(JSONException e){throw new IllegalStateException(e);}}
 File wave(){return new File(directory,"wave-"+Math.max(1,i("seq"))+".wav");}
 void save()throws IOException{try{data.put("updated",System.currentTimeMillis());File tmp=new File(directory,"job.new");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}try{Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}catch(JSONException e){throw new IOException(e);}}
 SpeechProfile profile(){return new SpeechProfile(s("engine"),s("voice"),s("language"),b("online"),(float)data.optDouble("rate",1));}
 void clearTemporary(){File[] files=directory.listFiles();if(files!=null)for(File f:files)if(f.isFile()&&!f.equals(file)&&!f.getName().equals("job.new"))f.delete();}
 void discard(){clearTemporary();new File(directory,"job.new").delete();file.delete();directory.delete();}
}
